CREATE TYPE ns16;
CREATE FUNCTION ns16_in(cstring) RETURNS ns16 AS 'MODULE_PATHNAME' LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
CREATE FUNCTION ns16_out(ns16) RETURNS cstring AS 'MODULE_PATHNAME' LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
CREATE FUNCTION ns16_recv(internal) RETURNS ns16 AS 'MODULE_PATHNAME' LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
CREATE FUNCTION ns16_send(ns16) RETURNS bytea AS 'MODULE_PATHNAME' LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
CREATE TYPE ns16 (INPUT=ns16_in, OUTPUT=ns16_out, RECEIVE=ns16_recv, SEND=ns16_send, INTERNALLENGTH=16, ALIGNMENT=double, STORAGE=plain);
CREATE FUNCTION ns16_from_int8(bigint) RETURNS ns16 AS 'MODULE_PATHNAME' LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
CREATE CAST (bigint AS ns16) WITH FUNCTION ns16_from_int8(bigint);
CREATE FUNCTION ns16_part(ns16) RETURNS bigint AS 'MODULE_PATHNAME' LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
CREATE FUNCTION ns16_cmp(ns16,ns16) RETURNS int AS 'MODULE_PATHNAME' LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
CREATE FUNCTION ns16_hash(ns16) RETURNS int AS 'MODULE_PATHNAME' LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
CREATE FUNCTION ns16_lt(ns16,ns16) RETURNS bool AS 'MODULE_PATHNAME' LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
CREATE OPERATOR < (LEFTARG=ns16,RIGHTARG=ns16,PROCEDURE=ns16_lt,COMMUTATOR='>',NEGATOR='>=',RESTRICT=scalarltsel,JOIN=scalarltjoinsel);
CREATE FUNCTION ns16_le(ns16,ns16) RETURNS bool AS 'MODULE_PATHNAME' LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
CREATE OPERATOR <= (LEFTARG=ns16,RIGHTARG=ns16,PROCEDURE=ns16_le,COMMUTATOR='>=',NEGATOR='>',RESTRICT=scalarlesel,JOIN=scalarlejoinsel);
CREATE FUNCTION ns16_eq(ns16,ns16) RETURNS bool AS 'MODULE_PATHNAME' LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
CREATE OPERATOR = (LEFTARG=ns16,RIGHTARG=ns16,PROCEDURE=ns16_eq,COMMUTATOR='=',NEGATOR='<>',RESTRICT=eqsel,JOIN=eqjoinsel,HASHES,MERGES);
CREATE FUNCTION ns16_ge(ns16,ns16) RETURNS bool AS 'MODULE_PATHNAME' LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
CREATE OPERATOR >= (LEFTARG=ns16,RIGHTARG=ns16,PROCEDURE=ns16_ge,COMMUTATOR='<=',NEGATOR='<',RESTRICT=scalargesel,JOIN=scalargejoinsel);
CREATE FUNCTION ns16_gt(ns16,ns16) RETURNS bool AS 'MODULE_PATHNAME' LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
CREATE OPERATOR > (LEFTARG=ns16,RIGHTARG=ns16,PROCEDURE=ns16_gt,COMMUTATOR='<',NEGATOR='<=',RESTRICT=scalargtsel,JOIN=scalargtjoinsel);
CREATE OPERATOR CLASS ns16_btree_ops DEFAULT FOR TYPE ns16 USING btree AS OPERATOR 1 <, OPERATOR 2 <=, OPERATOR 3 =, OPERATOR 4 >=, OPERATOR 5 >, FUNCTION 1 ns16_cmp(ns16,ns16);
CREATE OPERATOR CLASS ns16_hash_ops DEFAULT FOR TYPE ns16 USING hash AS OPERATOR 1 =, FUNCTION 1 ns16_hash(ns16);
CREATE OPERATOR CLASS ns16_minmax_ops DEFAULT FOR TYPE ns16 USING brin AS OPERATOR 1 <, OPERATOR 2 <=, OPERATOR 3 =, OPERATOR 4 >=, OPERATOR 5 >,
 FUNCTION 1 brin_minmax_opcinfo(internal), FUNCTION 2 brin_minmax_add_value(internal,internal,internal,internal), FUNCTION 3 brin_minmax_consistent(internal,internal,internal), FUNCTION 4 brin_minmax_union(internal,internal,internal);
CREATE FUNCTION ns16_to_int8(ns16) RETURNS bigint AS 'MODULE_PATHNAME' LANGUAGE C IMMUTABLE STRICT PARALLEL SAFE;
CREATE CAST (ns16 AS bigint) WITH FUNCTION ns16_to_int8(ns16);
