CREATE OPERATOR >= (LEFTARG=ns128,RIGHTARG=ns128,PROCEDURE=ns128_ge,COMMUTATOR='<=',NEGATOR='<',RESTRICT=scalargesel,JOIN=scalargejoinsel);
