CREATE OPERATOR CLASS ns128_minmax_ops DEFAULT FOR TYPE ns128 USING brin AS OPERATOR 1 <, OPERATOR 2 <=, OPERATOR 3 =, OPERATOR 4 >=, OPERATOR 5 >,
 FUNCTION 1 brin_minmax_opcinfo(internal), FUNCTION 2 brin_minmax_add_value(internal,internal,internal,internal), FUNCTION 3 brin_minmax_consistent(internal,internal,internal), FUNCTION 4 brin_minmax_union(internal,internal,internal);
CREATE FUNCTION clock_ns() RETURNS bigint AS 'MODULE_PATHNAME' LANGUAGE C VOLATILE PARALLEL SAFE;
CREATE FUNCTION clock_ns16() RETURNS ns16 AS 'MODULE_PATHNAME' LANGUAGE C VOLATILE PARALLEL SAFE;
